mapper.insert:
/* insertChcTrlInsp - kim.seong.ok */
INSERT INTO SBD110 ( TRL_INSP_RSVT_MNG_NO /* 심리검사예약관리번호 */ ,INDEX_SN /* 색인일렬번호(심리검사선택그룹구분) */ ,CMMNS_TRL_INSP_LCLAS_SE_CD /* 공통심리검사대분류구분코드 */ ,CMMNS_TRL_INSP_SCLAS_SE_CD /* 공통심리검사소분류구분코드 */ ,FRST_RGTR_ID /* 최초등록자아이디 */ ,FRST_REG_DT /* 최초등록일시 */ ,LAST_MDFR_ID /* 최종수정자아이디 */ ,LAST_MDFCN_DT /* 최종수정일시 */ ) VALUES (
#{TRL_INSP_RSVT_MNG_NO}, /* 심리검사예약관리번호 */ #{INDEX_SN}, /* 색인일렬번호(심리검사선택그룹구분) */ #{CMMNS_TRL_INSP_LCLAS_SE_CD}, /* 공통심리검사대분류구분코드 */ #{CMMNS_TRL_INSP_SCLAS_SE_CD}, /* 공통심리검사소분류구분코드 */ #{FRST_RGTR_ID}, /* 최초등록자아이디 */ SYSDATE, /* 최초등록일시 */ #{LAST_MDFR_ID}, /* 최종수정자아이디 */ SYSDATE /* 최종수정일시 */ )

mapper.select:
/* selectChcTrlInsp - kim.seong.ok */
SELECT
TRL_INSP_RSVT_MNG_NO /* 심리검사예약관리번호 */ ,INDEX_SN /* 색인일렬번호(심리검사선택그룹구분) */ ,CMMNS_TRL_INSP_LCLAS_SE_CD /* 공통심리검사대분류구분코드 */ ,CMMNS_TRL_INSP_SCLAS_SE_CD /* 공통심리검사소분류구분코드 */ ,FRST_RGTR_ID /* 최초등록자아이디 */ ,TO_CHAR(FRST_REG_DT, 'YYYY-MM-DD HH24:MI:SS') AS FRST_REG_DT ,LAST_MDFR_ID /* 최종수정자아이디 */ ,TO_CHAR(LAST_MDFCN_DT, 'YYYY-MM-DD HH24:MI:SS') AS LAST_MDFCN_DT
FROM SBD110 WHERE TRL_INSP_RSVT_MNG_NO = #{TRL_INSP_RSVT_MNG_NO}

mapper.update:
/* deleteTrlInspRsvtMngDetail - kim.seong.ok */


UPDATE SBD100 SET

DEL_YN = 'Y',
LAST_MDFR_ID               = #{LAST_MDFR_ID},                           /* 최종수정자아이디        */
LAST_MDFCN_DT              = SYSDATE                                   /* 최종수정일시           */

WHERE TRL_INSP_RSVT_MNG_NO = #{TRL_INSP_RSVT_MNG_NO}
AND USER_ID = #{USER_ID}

mapper.select:

/* getTrlInspRsvtMngDailyListTotalCount - kim.seong.ok */

SELECT

    COUNT(*)

FROM SBD100
    WHERE USER_ID = #{USER_ID}
    AND RSVT_YMD = #{SEARCH_DATE}
    AND DEL_YN = 'N'

/* selectTrlInspRsvtMngDailyList - kim.seong.ok */
WITH TIRM AS ( SELECT A.*, (SELECT D.CMMNS_CD_VALUE_NM FROM SAC100 D /* 공통코드 값 */ WHERE D.CMMNS_CD_ID = 'CMMNS_TRL_INSP_SCLAS_SE_CD' AND D.CMMNS_CD_VALUE = B.CMMNS_TRL_INSP_SCLAS_SE_CD) AS CMMNS_TRL_INSP_SCLAS_SE_NM FROM SBD100 A JOIN SBD110 B ON A.TRL_INSP_RSVT_MNG_NO = B.TRL_INSP_RSVT_MNG_NO WHERE A.USER_ID = #{USER_ID} AND A.RSVT_YMD = #{SEARCH_DATE} AND A.DEL_YN = 'N'
) SELECT TRL_INSP_RSVT_MNG_NO /* 심리검사예약관리번호 */ ,INTRVN_DSCSN_MNG_NO /* 개입상담관리번호 */ ,TASKWK_SYS_SE_CD /* 업무시스템구분코드 */ ,INST_NO /* 기관번호 */ ,USER_ID /* 사용자 아이디 */ ,DEC_B64(CLR_NM_ENCPT) AS CLR_NM_ENCPT /* 접수자(상담사)명암호화 */ ,DEC_B64(RSVCTM_NM_ENCPT) AS RSVCTM_NM_ENCPT /* 예약자명암호화 */ ,RSVT_YMD /* 예약일자 */ ,DEC_B64(TELNO_ENCPT) AS TELNO_ENCPT /* 전화번호암호화 */ ,DEC_B64(MBL_TELNO_ENCPT) AS MBL_TELNO_ENCPT /* 휴대전화번호암호화 */ ,GRADE_SE_CD /* 학년구분코드 */ ,GRADE_NM /* 학년명 */ ,REG_YMD /* 등록일자 */ ,RM_CN /* 비고내용 */ ,RSVT_CHRCTR_SNDNG_YN /* 예약문자발송여부 */ ,DEL_YN /* 삭제여부 */ ,FRST_RGTR_ID /* 최초등록자아이디 */ ,TO_CHAR(FRST_REG_DT, 'YYYY-MM-DD HH24:MI:SS') AS FRST_REG_DT ,LAST_MDFR_ID /* 최종수정자아이디 */ ,TO_CHAR(LAST_MDFCN_DT, 'YYYY-MM-DD HH24:MI:SS') AS LAST_MDFCN_DT ,WM_CONCAT(CMMNS_TRL_INSP_SCLAS_SE_NM) as CMMNS_TRL_INSP_SCLAS_SE_NM FROM TIRM GROUP BY TRL_INSP_RSVT_MNG_NO ,INTRVN_DSCSN_MNG_NO ,TASKWK_SYS_SE_CD ,INST_NO ,USER_ID ,CLR_NM_ENCPT ,RSVCTM_NM_ENCPT ,RSVT_YMD ,TELNO_ENCPT ,MBL_TELNO_ENCPT ,GRADE_SE_CD ,GRADE_NM ,REG_YMD ,RM_CN ,RSVT_CHRCTR_SNDNG_YN ,DEL_YN ,FRST_RGTR_ID ,FRST_REG_DT ,LAST_MDFR_ID ,LAST_MDFCN_DT
